intro:
Returns an outer_iterator to the first element of the lazy_split_view.

Let base_ be the underlying view and current_ be the underlying caching object (may not be present).

1) Equivalent to
constexpr auto begin()
{
    if constexpr (ranges::forward_range<V>)
        return /*outer_iterator*/</*simple_view*/<V>>{*this, ranges::begin(base_)};
    else
    {
        current_ = ranges::begin(base_);
        return /*outer_iterator*/<false>{*this};
    }
}

2) Equivalent to return /*outer_iterator*/<true>{*this, ranges::begin(base_)};.

examples.code:
#include <ranges>
#include <string_view>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::string_view input = "one,two";
    auto split = std::views::split(input, ',');
    auto first = split.begin();
    auto end = split.end();
    assert(first != end);
    auto word = *first;
    assert(std::ranges::distance(word) == 3);
    ++first;
    assert(first != end);
    auto lazy = std::views::lazy_split(input, ',');
    auto outer = lazy.begin();
    auto inner = (*outer).begin();
    assert(*inner == 'o');
    ++inner;
    assert(*inner == 'n');
    ++outer;
    assert(*(*outer).begin() == 't');
}
